import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLong()) return;

        long N = sc.nextLong();
        int M = sc.nextInt();

        int[] T = new int[M];
        long length = N;

        for (int i = 0; i < M; i++) {
            T[i] = sc.nextInt();
            length = length - length / T[i];
        }

        int K = (int) Math.min(length, 10000L);

        StringBuilder sb = new StringBuilder();
        for (int j = 1; j <= K; j++) {
            long pos = j;
            for (int i = M - 1; i >= 0; i--) {
                pos += (pos - 1) / (T[i] - 1);
            }
            sb.append(pos).append('\n');
        }

        System.out.print(sb.toString());
    }
}
